def max_sum_increasing_subsequence(arr, n):
    # Initialize the DP table where dp[i] represents the maximum sum ending at index i
    dp = [arr[0]] * n

    # Iterate through each element in the array starting from the second element
    for i in range(1, n):
        # Check all previous elements to see if there exists a larger element that can be appended to form an increasing subsequence
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + arr[i])

    # The maximum sum of the increasing subsequence is the maximum value in the DP table
    return max(dp)

