def find_kth(arr1, arr2, k1, k2, k):
    # Initialize pointers for both arrays
    i, j = 0, 0

    # Traverse through both arrays until we reach the k-th position
    while i < len(arr1) and j < len(arr2):
        if k > 1:
            k -= 1
            if arr1[i] < arr2[j]:
                i += 1
            else:
                j += 1
        elif k == 1:
            return min(arr1[i], arr2[j])

    # If one of the arrays is exhausted, return the remaining element from the other array
    return (arr1[i] if i < len(arr1) else arr2[j]) * k

